#include "stdlib/math/base/special/trunc2f.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/assert/is_infinite.h"
#include "stdlib/number/float32/base/exponent.h"
#include "stdlib/math/base/special/frexpf.h"
#include "stdlib/math/base/special/ldexpf.h"
#include "stdlib/math/base/special/absf.h"

/**
* Rounds single presicion float number to power of 2 towards zero
*
* @param x    number
* @return     rounded value
*
* @example
* float y = stdlib_base_trunc2f( 13.0 );
* // returns 8.0
*/

float stdlib_base_trunc2f( const float x ) {
	int32_t exp;
	float ax;
	float frac;
	float sign;

	if ( stdlib_base_is_nan( x ) || stdlib_base_is_infinite( x ) || x == 0.0f ) {
		return x;
	}

	if ( x < 0.0f ) {
		sign = -1.0f;
	} else {
		sign = 1.0f;
	}
	ax = stdlib_base_absf( x );
	stdlib_base_frexpf( x,&frac ,&exp );

	return sign * stdlib_base_ldexpf( 1.0f, exp-1 );
}
